"""Small, explicit input workbooks; generated without network access."""
from functools import lru_cache
from io import BytesIO
import datetime
from openpyxl import Workbook
from openpyxl.styles import Font,PatternFill,Alignment


@lru_cache(maxsize=1)
def input_templates():
    specs={
      'Шаблон_динамики.xlsx':('Динамика',['Скважина','Дата','Расход, м³/сут','Тип','Сезон','Группа'],['540',datetime.date(2025,11,1),120000,'отбор','2025-2026','ГСП-9']),
      'Шаблон_ГДИ.xlsx':('ГДИ',['Скважина','Дата','Q, тыс. м³/сут','Рпл, кгс/см2','Рзаб, кгс/см2','Метод','Исследование'],['540',datetime.date(2025,11,1),100,75,70,'Установившиеся отборы','1']),
      'Шаблон_реагирования.xlsx':('Реагирование',['Скважина','Дата','Горизонт','Уровень жидкости, м','Рпл привед., кгс/см2'],['540',datetime.date(2025,11,1),'Окский',42,75]),
      'Шаблон_давления_объекта.xlsx':('Давление объекта',['Дата','Пластовое давление, кгс/см2'],[datetime.date(2025,11,1),75]),
      'Шаблон_плана.xlsx':('План',['Группа','Месяц','Режим','План, млн м³'],['ГСП-9',datetime.date(2025,5,1),'закачка',150]),
      'Шаблон_групп.xlsx':('Группы',['Скважина','Группа','Подгруппа'],['540','ГСП-9','1']),
      'Шаблон_суточной_эксплуатации.xlsx':('Суточная эксплуатация',['Скважина','Дата','Тип','Часы работы','Объем газа, м³','Объем воды, м³','Обводненность','Рпл, кгс/см2','Рзаб, кгс/см2','Устьевое давление, кгс/см2','Давление в шлейфе, кгс/см2','Комментарий'],['540',datetime.date(2025,11,1),'отбор',18,90000,1.2,'Да',75,70,60,55,'']),
      'Шаблон_контроля_воды.xlsx':('Контроль воды',['Скважина','Дата','Обводненность','Расход воды, м³/сут','Минерализация, г/л','Комментарий'],['540',datetime.date(2025,11,1),'Да',1.2,80,'Проба сепаратора']),
      'Шаблон_замеров_забоя.xlsx':('Замеры забоя',['Скважина','Дата','Текущий забой, м','Диаметр шаблона, мм','Метод замера','Комментарий'],['540',datetime.date(2025,11,1),1200,58,'Шаблонировка','']),
      'Шаблон_конструкции.xlsx':('Конструкция',['Скважина','Дата конструкции','Элемент','Верх интервала, м','Низ интервала, м','Наружный диаметр, мм','Внутренний диаметр, мм','Комментарий'],['540',datetime.date(2025,11,1),'Эксплуатационная колонна',0,1250,146,128,''])}
    out={}
    for filename,(name,columns,row) in specs.items():
        wb=Workbook();ws=wb.active;ws.title=name;ws.append(columns);ws.append(row);ws.freeze_panes='A2';ws.auto_filter.ref=ws.dimensions
        for cell in ws[1]:cell.font=Font(bold=True,color='FFFFFF');cell.fill=PatternFill('solid',fgColor='16746C');cell.alignment=Alignment(wrap_text=True,vertical='center')
        ws.row_dimensions[1].height=34
        for column in ws.columns:
            ws.column_dimensions[column[0].column_letter].width=max(18,min(35,len(str(column[0].value))+2))
            for cell in column[1:]:
                if isinstance(cell.value,datetime.date):cell.number_format='DD.MM.YYYY'
        notes=wb.create_sheet('Инструкция');notes.append(['Заполните первый лист своими данными; пример во второй строке замените или удалите.'])
        notes.append(['Одна строка — одно измерение. Даты — календарные даты Excel. Единицы указаны в заголовках.'])
        notes.append(['Для ГДИ нужно не менее трёх режимов с разными положительными Q на исследование: по двум точкам коэффициенты a и b не определяются надёжно.'])
        notes.append(['Для реагирования допустим уровень, давление или оба показателя. Пустые значения не заменяйте нулем.'])
        notes.append(['Эксплуатация: часы от 0 до 24; объем газа и воды — фактический объем за календарные сутки. Расход в часы работы вычисляется из объема и часов. Пустые часы неизвестны и не заменяются на 24.'])
        notes.append(['Вода: Да / Нет / Неизвестно. Пустое значение означает отсутствие сведений. Расход в журнале воды — отдельный замер, не суточный объем; он не суммируется за сезон.'])
        notes.append(['Забой и конструкция: глубины в метрах от одного нуля. Конструкция — полный снимок на дату; каждый элемент или интервал отдельной строкой с той же датой. Примеры элементов: колонна, НКТ, перфорация, пакер, открытый ствол.'])
        notes.append(['План: одна строка — одна группа, один месяц и один режим (отбор или закачка). В «Месяце» любая дата месяца; объём в млн м³ (единица берётся из заголовка: «тыс. м³», «млрд м³»).'])
        notes.append(['Загруженные значения обрабатываются как наблюдения. Удалите пример перед загрузкой своих данных. CSV/TSV с теми же заголовками также поддерживаются.'])
        notes.column_dimensions['A'].width=110
        buf=BytesIO();wb.save(buf);out[filename]=buf.getvalue()
    return out
